@startuml

class User {}

class Student extends User {
  + name : string
  + email : string
}

class Tutor extends User {
  + name : string
  + email : string
  + bankAccount : string
}

class Subject {
  + name : string
}

class ExpertiseLevel {
  + level : string
}

class TutoringOffer {
  + expertiseLevel : ExpertiseLevel
  + hourlyPrice : double
}

class Availability {
  + dayOfWeek : string
  + startTime : time
  + endTime : time
}

class TutoringRequest {
  + requestedLevel : ExpertiseLevel
  + targetDate : date
  + targetTime : time
}

class TutoringSession {
  + actualDate : date
  + actualTime : time
  + status : string
  + pricePaid : double
}

class Payment {
  + amount : double
  + method : string
}

class TutorOfTheMonthAward {
  + month : string
}

Student "1" -- "*" TutoringRequest : makes
Tutor "1" -- "*" TutoringOffer : offers
Tutor "1" -- "*" Availability : specifies
Tutor "1" -- "*" TutoringOffer : provides
TutoringOffer "*" -- "1" Subject : for
TutoringOffer "*" -- "1" Tutor : offered by
TutoringRequest "*" -- "1" Tutor : sent to
TutoringRequest "*" -- "1" Student : from
TutoringRequest "0..1" -- "0..1" TutoringSession : becomes
TutoringSession "*" -- "1" Tutor : conducted by
TutoringSession "*" -- "1" Student : attended by
TutoringSession "1" -- "0..1" Payment : results in
TutorOfTheMonthAward "*" -- "1" Subject : for
TutorOfTheMonthAward "*" -- "1" Tutor : awarded to

@enduml

